'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createCache } = require('./src/cache');

function deferred() {
  let resolve, reject;
  const promise = new Promise((yes, no) => { resolve = yes; reject = no; });
  return { promise, resolve, reject };
}
function observe(promise) {
  return promise.then(value => ({ value }), reason => ({ reason }));
}

for (const mutation of ['invalidate', 'clear', 'set']) {
  for (const outcome of ['resolve', 'reject']) {
    for (const order of ['old-first', 'new-first']) {
      test(`${mutation}: obsolete ${outcome}, ${order}`, async () => {
        let time = 0;
        let calls = 0;
        const old = deferred();
        const fresh = deferred();
        const cache = createCache({ now: () => time, ttlMs: 10,
          load: () => (++calls === 1 ? old.promise : fresh.promise) });
        const oldReader = observe(cache.get('key'));
        const oldWaiter = observe(cache.get('key'));
        await Promise.resolve();
        assert.equal(calls, 1);
        if (mutation === 'clear') cache.clear();
        else if (mutation === 'set') {
          cache.set('key', 'set-value');
          assert.equal(await cache.get('key'), 'set-value');
          time = 10;
        } else cache.invalidate('key');
        const freshReader = cache.get('key');
        await Promise.resolve();
        assert.equal(calls, 2);
        const reason = { obsolete: true };
        const settleOld = async () => {
          old[outcome](outcome === 'resolve' ? 'stale' : reason);
          const expected = outcome === 'resolve' ? { value: 'stale' } : { reason };
          assert.deepEqual(await oldReader, expected);
          assert.deepEqual(await oldWaiter, expected);
        };
        if (order === 'old-first') {
          await settleOld();
          assert.equal(cache.size, 0);
          const joined = cache.get('key');
          await Promise.resolve();
          assert.equal(calls, 2);
          fresh.resolve('fresh');
          assert.equal(await joined, 'fresh');
        } else {
          fresh.resolve('fresh');
          assert.equal(await freshReader, 'fresh');
          await settleOld();
        }
        assert.equal(await freshReader, 'fresh');
        assert.equal(await cache.get('key'), 'fresh');
        assert.equal(calls, 2);
      });
    }
  }
}

for (const failure of ['throw', 'reject', 'thenable']) {
  for (const reason of [new Error('load failed'), null, undefined, 0]) {
    test(`retry after ${failure}, reason ${String(reason)}`, async () => {
      let calls = 0;
      const cache = createCache({ load() {
        calls++;
        if (calls > 1) return 'retry';
        if (failure === 'throw') throw reason;
        if (failure === 'reject') return Promise.reject(reason);
        return { then(resolve, reject) { reject(reason); } };
      } });
      const first = observe(cache.get('key'));
      const second = observe(cache.get('key'));
      assert.strictEqual((await first).reason, reason);
      assert.strictEqual((await second).reason, reason);
      assert.equal(calls, 1);
      assert.equal(cache.size, 0);
      assert.equal(await cache.get('key'), 'retry');
      assert.equal(calls, 2);
    });
  }
}

test('repeated invalidations are distinct barriers without stored values', async () => {
  const gates = [deferred(), deferred(), deferred()];
  let calls = 0;
  const cache = createCache({ load: () => gates[calls++].promise });
  const readers = [cache.get('key')];
  cache.invalidate('key');
  readers.push(cache.get('key'));
  cache.invalidate('key');
  readers.push(cache.get('key'));
  await Promise.resolve();
  assert.equal(calls, 3);
  for (const index of [1, 0, 2]) {
    gates[index].resolve(index);
    assert.equal(await readers[index], index);
    if (index !== 2) assert.equal(cache.size, 0);
  }
  assert.equal(await cache.get('key'), 2);
  assert.equal(calls, 3);
});

for (const mutation of ['invalidate', 'set', 'clear']) {
  test(`synchronous load ${mutation} detaches itself`, async () => {
    let calls = 0;
    let nested;
    const cache = createCache({ load() {
      if (++calls === 1) {
        if (mutation === 'clear') cache.clear();
        else if (mutation === 'set') cache.set('key', 'set-value');
        else cache.invalidate('key');
        nested = cache.get('key');
        return 'stale';
      }
      return 'fresh';
    } });
    assert.equal(await cache.get('key'), 'stale');
    assert.equal(await nested, mutation === 'set' ? 'set-value' : 'fresh');
    assert.equal(await cache.get('key'), mutation === 'set' ? 'set-value' : 'fresh');
    assert.equal(calls, mutation === 'set' ? 1 : 2);
  });
}

test('load reads its own key without starting another flight', async () => {
  let calls = 0;
  let nested;
  const cache = createCache({ load(key) {
    calls++;
    assert.equal(arguments.length, 1);
    assert.equal(key, 'key');
    nested = cache.get(key);
    return { then(resolve) { resolve('value'); } };
  } });
  assert.equal(await cache.get('key'), 'value');
  assert.equal(await nested, 'value');
  assert.equal(calls, 1);
});

test('TTL starts at commit and expires at its exact boundary', async () => {
  let time = 0;
  let calls = 0;
  const gate = deferred();
  const cache = createCache({ now: () => time, ttlMs: 10,
    load: () => ++calls === 1 ? gate.promise : 'fresh' });
  const reader = cache.get('key');
  await Promise.resolve();
  time = 100;
  gate.resolve('value');
  assert.equal(await reader, 'value');
  time = 109;
  assert.equal(await cache.get('key'), 'value');
  assert.equal(cache.size, 1);
  time = 110;
  assert.equal(cache.size, 0);
  assert.equal(await cache.get('key'), 'fresh');
  assert.equal(calls, 2);
});

test('obsolete loads do not extend the TTL of a set value', async () => {
  let time = 0;
  let calls = 0;
  const gate = deferred();
  const cache = createCache({ now: () => time, ttlMs: 10,
    load: () => ++calls === 1 ? gate.promise : 'fresh' });
  const reader = cache.get('key');
  await Promise.resolve();
  time = 5;
  assert.equal(cache.set('key', 'set-value'), undefined);
  time = 14;
  gate.resolve('stale');
  assert.equal(await reader, 'stale');
  assert.equal(await cache.get('key'), 'set-value');
  time = 15;
  assert.equal(await cache.get('key'), 'fresh');
  assert.equal(calls, 2);
});

test('zero TTL shares unsettled work but never a settled value', async () => {
  let calls = 0;
  const gate = deferred();
  const cache = createCache({ ttlMs: 0, now: () => 0,
    load: () => ++calls === 1 ? gate.promise : 'fresh' });
  const first = cache.get('key');
  const second = cache.get('key');
  await Promise.resolve();
  assert.equal(calls, 1);
  assert.equal(cache.size, 0);
  gate.resolve('value');
  assert.equal(await first, 'value');
  assert.equal(await second, 'value');
  assert.equal(cache.size, 0);
  assert.equal(await cache.get('key'), 'fresh');
  assert.equal(calls, 2);
});

test('clear detaches all keys but preserves original reader outcomes', async () => {
  const a = deferred();
  const b = deferred();
  const calls = new Map();
  const cache = createCache({ load(key) {
    const count = (calls.get(key) || 0) + 1;
    calls.set(key, count);
    return count === 1 ? (key === 'a' ? a.promise : b.promise) : `fresh-${key}`;
  } });
  const readers = [cache.get('a'), observe(cache.get('b'))];
  await Promise.resolve();
  cache.set('stored', null);
  assert.equal(cache.clear(), undefined);
  assert.equal(cache.size, 0);
  assert.equal(await cache.get('a'), 'fresh-a');
  assert.equal(await cache.get('b'), 'fresh-b');
  a.resolve('old-a');
  b.reject('old-b');
  assert.equal(await readers[0], 'old-a');
  assert.deepEqual(await readers[1], { reason: 'old-b' });
  assert.equal(await cache.get('a'), 'fresh-a');
  assert.equal(await cache.get('b'), 'fresh-b');
});

test('identity keys, nullish values, and independent instances remain supported', async () => {
  let calls = 0;
  const cache = createCache({ now: () => 0, load: key => { calls++; return key; } });
  const object = {};
  assert.equal(await cache.get(object), object);
  assert.equal(await cache.get(object), object);
  assert.equal(await cache.get(NaN), NaN);
  assert.equal(await cache.get(NaN), NaN);
  assert.equal(calls, 2);
  cache.set(0, undefined);
  assert.equal(await cache.get(-0), undefined);
  cache.set('null', null);
  assert.equal(await cache.get('null'), null);
  assert.equal(cache.size, 4);
  assert.equal(cache.invalidate('missing'), undefined);
  const other = createCache({ load: () => 'other' });
  assert.equal(await other.get(object), 'other');
  assert.equal(await cache.get(object), object);
});

